  { key: '/settings/backup', icon: <DatabaseOutlined />, label: 'النسخ الاحتياطي', module: 'backup' },
  {
    key: 'accounts',
    icon: <DollarOutlined />,
    label: 'الحسابات',
    children: [
      { key: '/fees', icon: <DollarOutlined />, label: 'الأتعاب', module: 'fees' },
