import { useState, useEffect } from 'react';
import { Card, Table, Tag, Row, Col, Statistic, message } from 'antd';
import { BellOutlined, CalendarOutlined, NotificationOutlined } from '@ant-design/icons';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';

export default function Notifications() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    api.get('/notifications').then(res => {
      setNotifications(res.data.data || res.data || []);
    }).catch(() => message.error('تعذر تحميل التنبيهات'))
    .finally(() => setLoading(false));
  }, []);

  const urgencyColors: Record<string, string> = {
    high: 'red',
    medium: 'orange',
    low: 'blue',
  };

  const urgencyLabels: Record<string, string> = {
    high: 'عاجل',
    medium: 'متوسط',
    low: 'منخفض',
  };

  const columns = [
    {
      title: 'النوع',
      dataIndex: 'type',
      render: (v: string) => v === 'session' ? <CalendarOutlined /> : <NotificationOutlined />,
      width: 60,
    },
    { title: 'العنوان', dataIndex: 'title' },
    { title: 'الوصف', dataIndex: 'description', ellipsis: true },
    { title: 'التاريخ', dataIndex: 'date' },
    { title: 'رقم القضية', dataIndex: 'caseNumber', render: (v: string) => v || '—' },
    { title: 'المحكمة', dataIndex: 'courtName', render: (v: string) => v || '—' },
    {
      title: 'الأولوية',
      dataIndex: 'urgency',
      render: (v: string) => <Tag color={urgencyColors[v]}>{urgencyLabels[v] || v}</Tag>,
    },
  ];

  const highCount = notifications.filter(n => n.urgency === 'high').length;
  const mediumCount = notifications.filter(n => n.urgency === 'medium').length;
  const lowCount = notifications.filter(n => n.urgency === 'low').length;

  return (
    <div>
      <PageHeader
        title="التنبيهات"
        subtitle="الجلسات القادمة والإعلانات التي تحتاج متابعة"
      />

      <Row gutter={[12, 12]} style={{ marginBottom: 10 }}>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات عاجلة"
              value={highCount}
              prefix={<BellOutlined />}
              valueStyle={{ color: '#c0392b' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات متوسطة"
              value={mediumCount}
              valueStyle={{ color: '#e67e22' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات منخفضة"
              value={lowCount}
              valueStyle={{ color: '#2980b9' }}
            />
          </Card>
        </Col>
      </Row>

      <Card size="small">
        <Table
          columns={columns}
          dataSource={notifications}
          rowKey="id"
          loading={loading}
          size="small"
          pagination={{ pageSize: 10 }}
          locale={{ emptyText: 'لا توجد تنبيهات حالياً' }}
        />
      </Card>
    </div>
  );
}

